using System.Net; using System.Text; using System.Text.Json;
namespace InovaGed.Environment.Doctor.Quality;
public static class QualityReportWriter {public static async Task WriteAsync(string root,QualityGateReport report,CancellationToken ct){var dir=Path.Combine(root,"artifacts/quality-gate");Directory.CreateDirectory(dir);var options=new JsonSerializerOptions{WriteIndented=true};options.Converters.Add(new System.Text.Json.Serialization.JsonStringEnumConverter());var json=JsonSerializer.Serialize(report,options);await File.WriteAllTextAsync(Path.Combine(dir,"quality-gate-report.json"),json,ct);await File.WriteAllTextAsync(Path.Combine(dir,"quality-gate-2-report.json"),json,ct);var counts=report.Checks.GroupBy(x=>x.Status).ToDictionary(x=>x.Key,x=>x.Count());int Count(QualityStatus s)=>counts.GetValueOrDefault(s);var md=new StringBuilder($"# {report.Name}\n\n- **Status geral:** {report.Status.ToString().ToUpperInvariant()}\n- **Data/hora (UTC):** {report.GeneratedAtUtc:O}\n- **Ambiente:** {report.Environment}\n- **Connection string sanitizada:** {report.ConnectionString}\n- **Total de checks:** {report.Checks.Count}\n- **Checks OK:** {Count(QualityStatus.Pass)}\n- **Warnings:** {Count(QualityStatus.Warning)}\n- **Falhas:** {Count(QualityStatus.Fail)}\n\n| Status | Grupo | Mensagem | Impacto | Ação recomendada | Script/recurso |\n|---|---|---|---|---|---|\n");foreach(var x in report.Checks)md.AppendLine($"| {x.Status.ToString().ToUpperInvariant()} | {Esc(x.Check)} | {Esc(x.Message)} | {Esc(x.Impact)} | {Esc(x.Action)} | {Esc(x.Script??x.Resource)} |");await File.WriteAllTextAsync(Path.Combine(dir,"quality-gate-report.md"),md.ToString(),ct);await File.WriteAllTextAsync(Path.Combine(dir,"quality-gate-2-report.md"),md.ToString(),ct);var html=$"<!doctype html><html lang=\"pt-BR\"><meta charset=\"utf-8\"><title>{report.Name}</title><style>body{{font:14px system-ui;margin:2rem}}table{{border-collapse:collapse}}td,th{{border:1px solid #ccc;padding:.5rem}}.Fail{{color:#b00020}}.Warning{{color:#9a6700}}</style><h1>{report.Name}</h1><p>Status geral: <strong class=\"{report.Status}\">{report.Status.ToString().ToUpperInvariant()}</strong></p><p>{report.GeneratedAtUtc:O} · {WebUtility.HtmlEncode(report.Environment)} · {WebUtility.HtmlEncode(report.ConnectionString)}</p><table><thead><tr><th>Status</th><th>Grupo</th><th>Mensagem</th><th>Impacto</th><th>Ação recomendada</th><th>Script/recurso</th></tr></thead><tbody>{string.Join("",report.Checks.Select(x=>$"<tr><td class='{x.Status}'>{x.Status.ToString().ToUpperInvariant()}</td><td>{H(x.Check)}</td><td>{H(x.Message)}</td><td>{H(x.Impact)}</td><td>{H(x.Action)}</td><td>{H(x.Script??x.Resource)}</td></tr>"))}</tbody></table></html>";await File.WriteAllTextAsync(Path.Combine(dir,"quality-gate-report.html"),html,ct);}private static string Esc(string? s)=>(s??"-").Replace("|","\\|").Replace("\n"," ");private static string H(string? s)=>WebUtility.HtmlEncode(s??"-");}
